describe("String / 容器字面量接收者的形参字面量拒", () => {
  it.each(REFUSE)("拒 %s", async (expr, messages) => {
    expect(await diags(expr)).toEqual(messages.split(" || "));
  });

  it.each(ACCEPT)("收 %s", async (expr) => {
    expect(await diags(expr)).toEqual([]);
  });
});
